function inspectFallback(val) {
  const domains = Object.keys(val);
  if (domains.length === 0) {
    return "{}";
  }
  let result = "{\n";
  Object.keys(val).forEach((domain, i) => {
    result += formatDomain(domain, val[domain]);
    if (i < domains.length - 1) {
      result += ",";
    }
    result += "\n";
  });
  result += "}";
  return result;
}

function formatDomain(domainName, domainValue) {
