    const visitor = {};

    visitor[type] = function (path) {
      const evaluate = path.evaluate();
      expect(evaluate.confident).toBeFalsy();
      expect(evaluate.deopt.type).toEqual(expectedType);
    };

    traverse(
      parse(code, {
        plugins: ["*"],
      }),
      visitor,
    );
  });
}

